    {
      "qualname": "arrow/locales.py::SlavicBaseLocale._format_timeframe",
      "source": "def _format_timeframe(self, timeframe: TimeFrameLiteral, delta: int) -> str:
    f = self.timeframes[timeframe]
    d = abs(delta)
    if isinstance(f, Mapping):
        if d % 10 == 1 and d % 100 != 11:
            f = f["singular"]
        elif 2 <= d % 10 <= 4 and (d % 100 < 10 or d % 100 >= 20):
            f = f["dual"]
        else:
            f = f["plural"]
    return f.format(d)"
    },
    {
      "qualname": "arrow/locales.py::ArabicLocale._format_timeframe",
      "source": "def _format_timeframe(self, timeframe: TimeFrameLiteral, delta: int) -> str:
    f = self.timeframes[timeframe]
    d = abs(delta)
    if isinstance(f, Mapping):
        if d == 2:
            f = f["2"]
        elif 2 < d <= 10:
            f = f["ten"]
        else:
            f = f["higher"]
    return f.format(d)"
