    {
      "qualname": "arrow/locales.py::IcelandicLocale._format_timeframe",
      "source": "def _format_timeframe(self, timeframe: TimeFrameLiteral, delta: int) -> str:
    f = self.timeframes[timeframe]
    if isinstance(f, Mapping):
        if delta < 0:
            f = f["past"]
        elif delta > 0:
            f = f["future"]
        else:
            raise ValueError(
                "Icelandic Locale does not support units with a delta of zero. "
                "Please consider making a contribution to fix this issue."
            )
    return f.format(abs(delta))"
    },
    {
      "qualname": "arrow/locales.py::CzechLocale._format_timeframe",
      "source": "def _format_timeframe(self, timeframe: TimeFrameLiteral, delta: int) -> str:
    """Czech aware time frame format function, takes into account
    the differences between past and future forms."""
    ad = abs(delta)
    f = self.timeframes[timeframe]
    if isinstance(f, str):
        return f.format(ad)
    if delta == 0:
        k = "zero"
    elif delta < 0:
        k = "past"
    elif "future-singular" not in f:
        k = "future"
    elif 2 <= ad % 10 <= 4 and (ad % 100 < 10 or ad % 100 >= 20):
        k = "future-singular"
    else:
        k = "future-paucal"
    return f[k].format(ad)"
