      "source": "def _format_timeframe(
    self, timeframe: TimeFrameLiteral, delta: Union[float, int]
) -> str:
    """Hebrew couple of <timeframe> aware"""
    f = self.timeframes[timeframe]
    d = abs(trunc(delta))
