      "qualname": "arrow/locales.py::ThaiLocale._format_relative",
      "source": "def _format_relative(
    self,
    humanized: str,
    timeframe: TimeFrameLiteral,
    delta: Union[float, int],
) -> str:
    """Thai normally doesn't have any space between words"""
    if timeframe == "now":
        return humanized
    direction = self.past if delta < 0 else self.future
    r = direction.format(humanized)
    if timeframe == "seconds":
        r = r.replace(" ", "")
    return r"
