      "qualname": "arrow/parser.py::DateTimeParser._parse_token",
      "source": "def _parse_token(
    self,
    token: Any,
    value: Any,
    parts: _Parts,
) -> None:

    def handle_S(v):
        v = v.ljust(7, "0")
        seventh = int(v[6])
        rounding = int(v[5]) % 2 if seventh == 5 else (1 if seventh > 5 else 0)
        parts["microsecond"] = int(v[:6]) + rounding

    def handle_ampm(t, v):
        if v in (self.locale.meridians["am"], self.locale.meridians["AM"]):
            parts["am_pm"] = "am"
            if "hour" in parts and not 0 <= parts["hour"] <= 12:
                raise ParserMatchError(f"Hour token value must be between 0 and 12 inclusive for token {t!r}.")
        elif v in (self.locale.meridians["pm"], self.locale.meridians["PM"]):
            parts["am_pm"] = "pm"

    handlers = {
        "YYYY": lambda t, v: parts.update(year=int(v)),
        "YY": lambda t, v: parts.update(year=1900+int(v) if int(v)>68 else 2000+int(v)),
        "MMMM": lambda t, v: parts.update(month=self.locale.month_number(v.lower())),
        "MMM": lambda t, v: parts.update(month=self.locale.month_number(v.lower())),
        "MM": lambda t, v: parts.update(month=int(v)),
        "M": lambda t, v: parts.update(month=int(v)),
        "DDDD": lambda t, v: parts.update(day_of_year=int(v)),
        "DDD": lambda t, v: parts.update(day_of_year=int(v)),
        "DD": lambda t, v: parts.update(day=int(v)),
        "D": lambda t, v: parts.update(day=int(v)),
        "Do": lambda t, v: parts.update(day=int(v)),
        "dddd": lambda t, v: parts.update(day_of_week=[x.lower() for x in self.locale.day_names].index(v.lower())-1),
        "ddd": lambda t, v: parts.update(day_of_week=[x.lower() for x in self.locale.day_abbreviations].index(v.lower())-1),
        "HH": lambda t, v: parts.update(hour=int(v)),
        "H": lambda t, v: parts.update(hour=int(v)),
        "mm": lambda t, v: parts.update(minute=int(v)),
        "m": lambda t, v: parts.update(minute=int(v)),
        "ss": lambda t, v: parts.update(second=int(v)),
        "s": lambda t, v: parts.update(second=int(v)),
        "S": lambda t, v: handle_S(v),
        "X": lambda t, v: parts.update(timestamp=float(v)),
        "x": lambda t, v: parts.update(expanded_timestamp=int(v)),
        "ZZZ": lambda t, v: parts.update(tzinfo=TzinfoParser.parse(v)),
        "ZZ": lambda t, v: parts.update(tzinfo=TzinfoParser.parse(v)),
        "Z": lambda t, v: parts.update(tzinfo=TzinfoParser.parse(v)),
        "a": lambda t, v: handle_ampm(t, v),
        "A": lambda t, v: handle_ampm(t, v),
        "W": lambda t, v: parts.update(weekdate=v),
    }
    handler = handlers.get(token)
    if handler:
        handler(token, value)"
    }
